  reg  [2:0]  s3_io_in_r_rm;
  reg  [2:0]  io_out_bits_ctrl_r_rm;
  reg  [31:0] io_out_bits_ctrl_r_c;
  reg  [3:0]  io_out_bits_ctrl_r_ctrl_dataType;
  reg  [3:0]  io_out_bits_ctrl_r_ctrl_dataTypeB;
  reg         io_out_bits_ctrl_r_ctrl_mixPrecision;
  reg         io_out_bits_ctrl_r_ctrl_Sparisity;
  reg  [31:0] io_out_bits_ctrl_r_ctrl_DAddress;
  reg         io_out_bits_ctrl_r_ctrl_clear;
  reg  [7:0]  io_out_bits_ctrl_r_ctrl_M;
  reg  [7:0]  io_out_bits_ctrl_r_ctrl_N;
  reg  [7:0]  io_out_bits_ctrl_r_ctrl_K;
  reg  [3:0]  io_out_bits_ctrl_r_ctrl_OutputD_Idx_m_mix;
  reg  [4:0]  io_out_bits_ctrl_r_ctrl_OutputD_Idx_n_mix;
  reg  [5:0]  io_out_bits_ctrl_r_ctrl_OutputD_Idx_m_f32;
  reg  [5:0]  io_out_bits_ctrl_r_ctrl_OutputD_Idx_n_f32;
  reg  [2:0]  io_out_bits_ctrl_r_1_rm;
  reg  [31:0] io_out_bits_ctrl_r_1_c;
  reg  [3:0]  io_out_bits_ctrl_r_1_ctrl_dataType;
  reg  [3:0]  io_out_bits_ctrl_r_1_ctrl_dataTypeB;
  reg         io_out_bits_ctrl_r_1_ctrl_mixPrecision;
  reg         io_out_bits_ctrl_r_1_ctrl_Sparisity;
  reg  [31:0] io_out_bits_ctrl_r_1_ctrl_DAddress;
  reg         io_out_bits_ctrl_r_1_ctrl_clear;
  reg  [7:0]  io_out_bits_ctrl_r_1_ctrl_M;
  reg  [7:0]  io_out_bits_ctrl_r_1_ctrl_N;
  reg  [7:0]  io_out_bits_ctrl_r_1_ctrl_K;
  reg  [3:0]  io_out_bits_ctrl_r_1_ctrl_OutputD_Idx_m_mix;
  reg  [4:0]  io_out_bits_ctrl_r_1_ctrl_OutputD_Idx_n_mix;
  reg  [5:0]  io_out_bits_ctrl_r_1_ctrl_OutputD_Idx_m_f32;
  reg  [5:0]  io_out_bits_ctrl_r_1_ctrl_OutputD_Idx_n_f32;
  always @(posedge clock) begin
    if (reset) begin
      REG <= 1'h0;
      REG_1 <= 1'h0;
    end
    else begin
      REG <= io_in_valid;
      REG_1 <= REG;
    end
    if (io_in_valid) begin
      s2_io_in_r_special_case_valid <= _s1_io_out_special_case_valid;
      s2_io_in_r_special_case_bits_nan <= _s1_io_out_special_case_bits_nan;
      s2_io_in_r_special_case_bits_inf <= _s1_io_out_special_case_bits_inf;
      s2_io_in_r_early_overflow <= _s1_io_out_early_overflow;
      s2_io_in_r_prod_sign <= _s1_io_out_prod_sign;
      s2_io_in_r_shift_amt <= _s1_io_out_shift_amt;
      s2_io_in_r_exp_shifted <= _s1_io_out_exp_shifted;
      s2_io_in_r_may_be_subnormal <= _s1_io_out_may_be_subnormal;
      s2_io_in_r_rm <= _s1_io_out_rm;
      io_out_bits_ctrl_r_rm <= io_in_bits_ctrl_rm;
      io_out_bits_ctrl_r_c <= io_in_bits_ctrl_c;
      io_out_bits_ctrl_r_ctrl_dataType <= io_in_bits_ctrl_ctrl_dataType;
      io_out_bits_ctrl_r_ctrl_dataTypeB <= io_in_bits_ctrl_ctrl_dataTypeB;
      io_out_bits_ctrl_r_ctrl_mixPrecision <= io_in_bits_ctrl_ctrl_mixPrecision;
      io_out_bits_ctrl_r_ctrl_Sparisity <= io_in_bits_ctrl_ctrl_Sparisity;
      io_out_bits_ctrl_r_ctrl_DAddress <= io_in_bits_ctrl_ctrl_DAddress;
      io_out_bits_ctrl_r_ctrl_clear <= io_in_bits_ctrl_ctrl_clear;
      io_out_bits_ctrl_r_ctrl_M <= io_in_bits_ctrl_ctrl_M;
      io_out_bits_ctrl_r_ctrl_N <= io_in_bits_ctrl_ctrl_N;
      io_out_bits_ctrl_r_ctrl_K <= io_in_bits_ctrl_ctrl_K;
      io_out_bits_ctrl_r_ctrl_OutputD_Idx_m_mix <= io_in_bits_ctrl_ctrl_OutputD_Idx_m_mix;
      io_out_bits_ctrl_r_ctrl_OutputD_Idx_n_mix <= io_in_bits_ctrl_ctrl_OutputD_Idx_n_mix;
      io_out_bits_ctrl_r_ctrl_OutputD_Idx_m_f32 <= io_in_bits_ctrl_ctrl_OutputD_Idx_m_f32;
      io_out_bits_ctrl_r_ctrl_OutputD_Idx_n_f32 <= io_in_bits_ctrl_ctrl_OutputD_Idx_n_f32;
    end
    if (REG) begin
      s3_io_in_r_special_case_valid <= _s2_io_out_special_case_valid;
      s3_io_in_r_special_case_bits_nan <= _s2_io_out_special_case_bits_nan;
      s3_io_in_r_special_case_bits_inf <= _s2_io_out_special_case_bits_inf;
      s3_io_in_r_raw_out_sign <= _s2_io_out_raw_out_sign;
      s3_io_in_r_raw_out_exp <= _s2_io_out_raw_out_exp;
      s3_io_in_r_raw_out_sig <= _s2_io_out_raw_out_sig;
      s3_io_in_r_early_overflow <= _s2_io_out_early_overflow;
      s3_io_in_r_rm <= _s2_io_out_rm;
      io_out_bits_ctrl_r_1_rm <= io_out_bits_ctrl_r_rm;
      io_out_bits_ctrl_r_1_c <= io_out_bits_ctrl_r_c;
      io_out_bits_ctrl_r_1_ctrl_dataType <= io_out_bits_ctrl_r_ctrl_dataType;
      io_out_bits_ctrl_r_1_ctrl_dataTypeB <= io_out_bits_ctrl_r_ctrl_dataTypeB;
      io_out_bits_ctrl_r_1_ctrl_mixPrecision <= io_out_bits_ctrl_r_ctrl_mixPrecision;
      io_out_bits_ctrl_r_1_ctrl_Sparisity <= io_out_bits_ctrl_r_ctrl_Sparisity;
      io_out_bits_ctrl_r_1_ctrl_DAddress <= io_out_bits_ctrl_r_ctrl_DAddress;
      io_out_bits_ctrl_r_1_ctrl_clear <= io_out_bits_ctrl_r_ctrl_clear;
      io_out_bits_ctrl_r_1_ctrl_M <= io_out_bits_ctrl_r_ctrl_M;
      io_out_bits_ctrl_r_1_ctrl_N <= io_out_bits_ctrl_r_ctrl_N;
      io_out_bits_ctrl_r_1_ctrl_K <= io_out_bits_ctrl_r_ctrl_K;
      io_out_bits_ctrl_r_1_ctrl_OutputD_Idx_m_mix <=
        io_out_bits_ctrl_r_ctrl_OutputD_Idx_m_mix;
      io_out_bits_ctrl_r_1_ctrl_OutputD_Idx_n_mix <=
        io_out_bits_ctrl_r_ctrl_OutputD_Idx_n_mix;
      io_out_bits_ctrl_r_1_ctrl_OutputD_Idx_m_f32 <=
        io_out_bits_ctrl_r_ctrl_OutputD_Idx_m_f32;
      io_out_bits_ctrl_r_1_ctrl_OutputD_Idx_n_f32 <=
        io_out_bits_ctrl_r_ctrl_OutputD_Idx_n_f32;
    end
  end // always @(posedge)
  NaiveMultiplier multiplier (
    .clock           (clock),
    .io_a            ({1'h0, |(io_in_bits_a[14:7]), io_in_bits_a[6:0]}),
    .io_b            ({1'h0, |(io_in_bits_b[14:7]), io_in_bits_b[6:0]}),
    .io_regEnables_0 (io_in_valid),
    .io_result       (_multiplier_io_result)
  );
  FMUL_s1 s1 (
    .io_a                         (io_in_bits_a),
    .io_b                         (io_in_bits_b),
    .io_rm                        (io_in_bits_rm),
    .io_out_special_case_valid    (_s1_io_out_special_case_valid),
    .io_out_special_case_bits_nan (_s1_io_out_special_case_bits_nan),
    .io_out_special_case_bits_inf (_s1_io_out_special_case_bits_inf),
    .io_out_early_overflow        (_s1_io_out_early_overflow),
    .io_out_prod_sign             (_s1_io_out_prod_sign),
    .io_out_shift_amt             (_s1_io_out_shift_amt),
    .io_out_exp_shifted           (_s1_io_out_exp_shifted),
    .io_out_may_be_subnormal      (_s1_io_out_may_be_subnormal),
    .io_out_rm                    (_s1_io_out_rm)
  );
  FMUL_s2 s2 (
    .io_in_special_case_valid     (s2_io_in_r_special_case_valid),
    .io_in_special_case_bits_nan  (s2_io_in_r_special_case_bits_nan),
    .io_in_special_case_bits_inf  (s2_io_in_r_special_case_bits_inf),
    .io_in_early_overflow         (s2_io_in_r_early_overflow),
    .io_in_prod_sign              (s2_io_in_r_prod_sign),
    .io_in_shift_amt              (s2_io_in_r_shift_amt),
    .io_in_exp_shifted            (s2_io_in_r_exp_shifted),
