  wire [8:0] _near_path_mods_0_io_out_sig_raw;
  wire [3:0] _near_path_mods_0_io_out_lzc;
  wire       decode_a_isInf = (&(io_a[14:7])) & ~(|(io_a[6:0]));
  wire       decode_b_isInf = (&(io_b[14:7])) & ~(|(io_b[6:0]));
  wire       _GEN = io_a[7] | ~(|(io_a[14:7]));
  wire [7:0] raw_a_exp = {io_a[14:8], _GEN};
  wire [7:0] raw_a_sig = {|(io_a[14:7]), io_a[6:0]};
  wire       _GEN_0 = io_b[7] | ~(|(io_b[14:7]));
  wire [7:0] raw_b_exp = {io_b[14:8], _GEN_0};
  wire [7:0] raw_b_sig = {|(io_b[14:7]), io_b[6:0]};
