      io_out_bits_ctrl_r_ctrl_DAddress <= io_in_bits_ctrl_ctrl_DAddress;
      io_out_bits_ctrl_r_ctrl_clear <= io_in_bits_ctrl_ctrl_clear;
      io_out_bits_ctrl_r_ctrl_M <= io_in_bits_ctrl_ctrl_M;
      io_out_bits_ctrl_r_ctrl_N <= io_in_bits_ctrl_ctrl_N;
      io_out_bits_ctrl_r_ctrl_K <= io_in_bits_ctrl_ctrl_K;
      io_out_bits_ctrl_r_ctrl_OutputD_Idx_m_mix <= io_in_bits_ctrl_ctrl_OutputD_Idx_m_mix;
      io_out_bits_ctrl_r_ctrl_OutputD_Idx_n_mix <= io_in_bits_ctrl_ctrl_OutputD_Idx_n_mix;
      io_out_bits_ctrl_r_ctrl_OutputD_Idx_m_f32 <= io_in_bits_ctrl_ctrl_OutputD_Idx_m_f32;
      io_out_bits_ctrl_r_ctrl_OutputD_Idx_n_f32 <= io_in_bits_ctrl_ctrl_OutputD_Idx_n_f32;
    end
    if (REG & ~(~io_out_ready & REG_1)) begin
      io_out_bits_ctrl_r_1_rm <= io_out_bits_ctrl_r_rm;
